const operationIrreversible = `-- name: OperationIrreversible :one
SELECT (NOT EXISTS (
    SELECT 1 FROM pc.package_pins p
    JOIN pc.action_definitions d ON d.org_id = p.org_id AND d.version_id = p.version_id
    WHERE p.org_id = $1 AND d.operation = $2
        AND convert_from(d.canonical, 'UTF8')::jsonb ->> 'reversibility' IN ('reversible', 'compensatable')
))::bool AS irreversible
`

// Whether an operation counts as irreversible: its pinned definition says
// so, or no pinned definition describes it (HR-280, D84 E6).
func (q *Queries) OperationIrreversible(ctx context.Context, orgID ids.OrgID, operation string) (bool, error) {
	row := q.db.QueryRow(ctx, operationIrreversible, orgID, operation)
	var irreversible bool
	err := row.Scan(&irreversible)
	return irreversible, err
}

const operationsQuarantined = `-- name: OperationsQuarantined :one
SELECT EXISTS (
    SELECT 1 FROM pc.package_pins p
    JOIN pc.package_versions v ON v.org_id = p.org_id AND v.id = p.version_id
    JOIN pc.action_definitions d ON d.org_id = v.org_id AND d.version_id = v.id
    WHERE p.org_id = $1 AND v.state IN ('QUARANTINED', 'RETIRED')
        AND (d.operation = ANY($2::text[])
             OR EXISTS (SELECT 1 FROM unnest($3::text[]) pr WHERE starts_with(d.operation, pr)))
)::bool
`

// Whether a pinned definition of one of the operations (exact names, or
// prefixes "x." of "x.*") is QUARANTINED or RETIRED (D59).
func (q *Queries) OperationsQuarantined(ctx context.Context, orgID ids.OrgID, exact []string, prefixes []string) (bool, error) {
	row := q.db.QueryRow(ctx, operationsQuarantined, orgID, exact, prefixes)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

